def page():
    return {'id':PAGE_ID,'name':'Living Water · Candidate 04','canvas':{'w':1440,'h':960},'nodes':[], 'design_experiment':{'schema':'dore.design-experiment.v1','track':'living-water-homepage','candidate':'04','status':'design-candidate','source':'user-direction-2026-09-09','principles':['inherit-c01-after-page2','four-horizontal-currents','journal-four-movements-internal-only','never-show-W-labels','8:5-weighted-rhythm','weight-controls-span-and-dwell','asymmetric-current-phase','ambient-flow-always-on','dore-public-original-background','reuse-dore-search-241-registry','monochrome-page2','mature-light-engine-trial','C-three-good-godrays','D-react-bits-lightrays','viewport-fixed-light-switch','guide-cue-hidden-during-light-test','no-section-colors-on-page2','first-layer-only']}}

def install_workspace(base):
    original=base.workspace
    def workspace():
        w=original()
        if not any(p.get('id')==PAGE_ID for p in w.get('pages',[])):
            w['pages'].append(page());w=base.save(w)
        return w
    base.workspace=workspace

