JS=r'''<script>(function(){var section=document.getElementById('liveNav');if(!section)return;var wraps=[].slice.call(section.querySelectorAll('.stream-wrap'));var reduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;var raf=0;function update(){raf=0;if(reduced)return;var r=section.getBoundingClientRect(),range=Math.max(1,section.offsetHeight-innerHeight),p=Math.max(0,Math.min(1,-r.top/range));wraps.forEach(function(w){var speed=parseFloat(w.dataset.speed||'.15'),origin=parseFloat(w.dataset.origin||'0'),dir=w.classList.contains('b')||w.classList.contains('d')?1:-1;w.style.setProperty('--scroll-x',((origin+dir*p*speed)*innerWidth).toFixed(2)+'px')})}function queue(){if(!raf)raf=requestAnimationFrame(update)}addEventListener('scroll',queue,{passive:true});addEventListener('resize',queue);update();var c=document.getElementById('lightC'),d=document.getElementById('lightD'),buttons=[].slice.call(section.querySelectorAll('[data-light]'));buttons.forEach(function(btn){btn.addEventListener('click',function(){var mode=btn.dataset.light;c.classList.toggle('off',mode!=='c');d.classList.toggle('off',mode!=='d');buttons.forEach(function(b){b.classList.toggle('on',b===btn)})})})})();</script>'''

def render(edit=False):
    html=c01.render(edit)
    start=html.find('<section class="live-nav"')
    if start<0:return html
    end=html.find('</section>',start)
    if end<0:return html
    end+=len('</section>')
    html=html[:start]+NAV+html[end:]
    html=html.replace('</style>',CSS+'</style>',1)
    html=html.replace('</body>',JS+'</body>',1)
    return html
